function openCity(){showDialog('Cidade e momento',`${selectField('city-select','Cidade que você quer consultar',CITY_NAMES,state.city)}<p class="form-note">Sua cidade atual é <b>${esc(state.homeCity)}</b>. Nas outras cidades você consulta conteúdo sem publicar.</p>${selectField('moment-select','Seu momento',[['moro','Moro na cidade'],['chegando','Estou chegando'],['saindo','Estou saindo']],state.mode)}<div class="form-grid"><label class="field-label" data-moment="chegando">Data de chegada<input id="arrival-date" type="date" value="${state.arrival}" min="${dateISO()}"></label><label class="field-label" data-moment="saindo">Data da saída<input id="leave-date" type="date" value="${state.leaveDate}" min="${dateISO()}"></label><div class="full" data-moment="saindo">${selectField('destination-select','Destino',CITY_NAMES.filter(c=>c!==state.homeCity),state.dest)}</div></div>`,`${btn('Cancelar','close-dialog','','text')}${btn('Aplicar','apply-city','','filled')}`);momentFields(dialog,state.mode);$('#moment-select')?.addEventListener('change',e=>momentFields(dialog,e.target.value));}
// Rodada 10 (decisão do usuário): "Moro na cidade" não mostra campos de transferência;
// "Estou chegando" mostra só a chegada; "Estou saindo", a saída e o destino.
function momentFields(scope,mode){for(const el of scope.querySelectorAll('[data-moment]'))el.style.display=el.dataset.moment===mode?'':'none';}
function openSettings(){showDialog('Configurações',`<div class="settings-section">${field('profile-name','Seu nome',state.profile.name,'required maxlength="80" autocomplete=\"name\"')}${selectField('appearance-select','Aparência',[['auto','Automática'],['light','Clara'],['dark','Escura']],state.prefs.appearance)}${cityHasHoods(state.homeCity)?selectField('profile-hood','Seu bairro (opcional)',[['','Não informar'],...HOODS.filter(h=>h!=='Outro bairro').map(h=>[h,h])],state.profile.hood||''):''}<div class="choice"><span class="txt"><b>Mostrar meu bairro</b><small>Desligado, só a cidade aparece no que você publica.</small></span><md-switch id="privacy-hood" ${state.prefs.showHood?'selected':''} aria-label="Mostrar meu bairro"></md-switch></div><div class="choice"><span class="txt"><b>Convites de família</b><small>Permitir criar convites no seu perfil.</small></span><md-switch id="privacy-family" ${state.prefs.familyOnly?'selected':''} aria-label="Permitir convites de família"></md-switch></div><div class="list settings-links">${[['visibility_off','Ocultados','Perguntas que só você deixou de ver','open-hidden',''],['cancel','Pessoas bloqueadas','Quem você deixou de ver e de falar','open-blocked',''],['lock','Política de privacidade','O que guardamos e quem vê','open-legal','privacidade'],['gavel','Código de conduta','Como conviver e denunciar','open-legal','conduta']].map(([ic,t,s,a,v])=>`<button type="button" class="list-row" data-action="${a}" data-value="${v}">${icon(ic)}<span class="txt"><b>${t}</b><small>${s}</small></span>${icon('chevron_right')}</button>`).join('')}</div><p class="form-note">Dados de exemplo e alterações ficam neste dispositivo. Verificação de identidade, envio de avisos e cobrança estão no modo teste.</p></div>`,`${btn('Cancelar','close-dialog','','text')}${btn('Salvar','save-settings','','filled')}`);}
function openPrototype(){const official=['md-filled-button','md-outlined-text-field','md-dialog','md-select-option','md-switch','md-filter-chip','md-primary-tab'].every(n=>!!customElements.get(n));showDialog('Controles do protótipo',`<p class="form-note">Dados fictícios para testar as jornadas. Você pode publicar e editar exemplos; nenhuma mensagem é enviada para pessoas reais.</p><div class="choice">${icon(official?'check_circle':'error')}<span class="txt"><b>Material Web oficial · ${esc(MATERIAL_VERSION)}</b><small>${official?'Componentes oficiais carregados e incorporados ao HTML.':'Falha ao carregar os componentes.'}</small></span></div>${selectField('prototype-stage','Estágio da cidade',[['live','Cidade ativa'],['seed','Cidade começando']],state.stage)}${field('prototype-incoming','Famílias com transferência declarada',state.incoming,'type="number" min="0" max="10000"')}${selectField('prototype-portal','Resultado da consulta do CPF (entrada)',[['verified','Vínculo confirmado'],['notfound','Vínculo não localizado'],['pending','Em análise'],['error','Fonte fora do ar']],state.test?.portal||'verified')}${state.entry?.eligibility==='pending'?btn('Aprovar a análise pendente','entry-approve','','outlined','verified_user'):''}<div class="choice"><span class="txt"><b>Verificação de teste</b><small>Controle de leitura e publicação.</small></span><md-switch id="verified-test" ${state.profile.verified?'selected':''} aria-label="Perfil de teste verificado"></md-switch></div><div class="stack">${btn('Ver como dono do Bivaque','owner-open','','filled','shield_person')}${btn('Ver a entrada do zero','onboarding','','outlined','refresh')}${btn('Simular resposta a uma pergunta','simulate-answer','','outlined','forum')}${btn('Simular resposta na conversa','simulate-message','','outlined','chat_bubble')}${btn('Simular anúncio para um alerta','simulate-alert','','outlined','notifications')}${btn('Simular decisão do moderador','simulate-moderation','','outlined','shield_person')}${btn('Simular propostas de prestadores','simulate-proposals','','outlined','request_quote')}${state.myBiz?.live?btn('Simular contato no meu negócio','simulate-biz-contact','','outlined','chat_bubble'):''}</div><p class="form-note">As respostas de exemplo usam o assunto da pergunta. Se não houver uma indicação relacionada, o protótipo não inventa uma resposta.</p>`,`${btn('Recomeçar do zero','reset-prototype','','text')}${btn('Aplicar','apply-prototype','','filled')}`,'prototype');}
